drop policy if exists "own attempts" on public.attempts; drop policy if exists "own evidence slots" on public.evidence_slots; drop policy if exists "own mastery" on public.mastery; drop policy if exists "own snapshots" on public.context_snapshots; create policy "read own attempts" on public.attempts for select to authenticated using((select auth.uid())=user_id); create policy "read own evidence slots" on public.evidence_slots for select to authenticated using((select auth.uid())=user_id); create policy "read own mastery" on public.mastery for select to authenticated using((select auth.uid())=user_id); create policy "read own snapshots" on public.context_snapshots for select to authenticated using((select auth.uid())=user_id); create or replace function public.submit_attempt(p_objective_id text,p_exercise_version_id text,p_idempotency_key text,p_correct boolean,p_help_level text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_user_id uuid:=auth.uid();v_attempt_id uuid;v_slot_rows integer:=0;v_m4_eligible boolean;v_level integer;v_review_due_at timestamptz;begin if v_user_id is null then raise exception 'Authentication is required';end if;if p_idempotency_key is null or length(trim(p_idempotency_key))=0 or length(p_idempotency_key)>200 then raise exception 'Invalid idempotency key';end if;if p_help_level not in ('none','diagnosis','hint','solution')then raise exception 'Invalid help level';end if;select o.m4_eligible into v_m4_eligible from public.exercise_versions ev join public.objectives o on o.id=ev.objective_id where ev.id=p_exercise_version_id and ev.objective_id=p_objective_id;if not found then raise exception 'Exercise version does not belong to objective';end if;insert into public.attempts(user_id,objective_id,exercise_version_id,idempotency_key,correct,help_level)values(v_user_id,p_objective_id,p_exercise_version_id,p_idempotency_key,p_correct,p_help_level)on conflict(user_id,idempotency_key)do nothing returning id into v_attempt_id;if v_attempt_id is null then return jsonb_build_object('status','idempotent');end if;if p_help_level='none'then insert into public.evidence_slots(user_id,objective_id,exercise_version_id,attempt_id)values(v_user_id,p_objective_id,p_exercise_version_id,v_attempt_id)on conflict(user_id,objective_id,exercise_version_id)do nothing;get diagnostics v_slot_rows=row_count;end if;if v_slot_rows=0 then return jsonb_build_object('status','evidence_recorded');end if;select case when v_m4_eligible and count(*)filter(where a.correct)>=2 and count(distinct a.exercise_version_id)filter(where a.correct)>=2 and count(distinct(a.created_at at time zone 'utc')::date)filter(where a.correct)>=2 then 4 when count(*)filter(where a.correct)>=1 then 3 when count(*)>=2 then 2 when count(*)=1 then 1 else 0 end into v_level from public.attempts a join public.evidence_slots es on es.attempt_id=a.id where a.user_id=v_user_id and a.objective_id=p_objective_id and a.help_level='none';v_review_due_at:=now()+case v_level when 4 then interval '28 days' when 3 then interval '7 days' when 2 then interval '2 days' else interval '1 day' end;insert into public.mastery(user_id,objective_id,level,review_due_at)values(v_user_id,p_objective_id,v_level,v_review_due_at)on conflict(user_id,objective_id)do update set level=excluded.level,review_due_at=excluded.review_due_at;return jsonb_build_object('status','recomputed','mastery',jsonb_build_object('level',v_level,'reviewDueAt',v_review_due_at));end;$$; revoke all on function public.submit_attempt(text,text,text,boolean,text)from public; grant execute on function public.submit_attempt(text,text,text,boolean,text)to authenticated; grant usage on schema public to anon,authenticated; grant select on public.courses,public.units,public.topics,public.objectives,public.resources,public.exercise_versions to anon,authenticated; grant select on public.attempts,public.evidence_slots,public.context_snapshots,public.mastery to authenticated;;
